<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Inertia\Testing\AssertableInertia;
use Modules\Customer\Models\Customer;
use Modules\Sample\Models\Sample;
use Yuan\AdminCore\Audit\ImmutableActivity;
use Yuan\AdminCore\Testing\ModuleAssertions;

use function Pest\Laravel\delete;
use function Pest\Laravel\get;
use function Pest\Laravel\post;
use function Pest\Laravel\put;

// Contoh (generated by make:module): the AGENTS §8 cases for each declared action.

uses(RefreshDatabase::class);

/**
 * A valid form submission, as the create page sends it.
 *
 * @param  array<string, mixed>  $overrides
 * @return array<string, mixed>
 */
function sampleInput(array $overrides = []): array
{
    return [
        'nama' => 'Contoh Nama',
        'kode' => 'Contoh Kode',
        'catatan' => 'Catatan contoh',
        'jumlah' => 12,
        'tahun' => 2024,
        'berat' => 2.5,
        'harga' => 150000,
        'aktif' => true,
        'mulai_tanggal' => '2026-10-20',
        'selesai_pada' => '2026-10-20 09:30',
        'status' => 'draf',
        'customer_id' => Customer::factory()->create()->id,
        ...$overrides,
    ];
}

it('redirects guests to login', function (): void {
    $sample = Sample::factory()->create();

    ModuleAssertions::assertGuestRedirected('get', '/admin/samples');
    ModuleAssertions::assertGuestRedirected('get', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertGuestRedirected('get', '/admin/samples/create');
    ModuleAssertions::assertGuestRedirected('post', '/admin/samples');
    ModuleAssertions::assertGuestRedirected('get', "/admin/samples/{$sample->id}/edit");
    ModuleAssertions::assertGuestRedirected('put', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertGuestRedirected('delete', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertGuestRedirected('delete', '/admin/samples');
    ModuleAssertions::assertGuestRedirected('get', '/admin/samples/download');
});

it('needs the permission of each action', function (): void {
    $sample = Sample::factory()->create();

    ModuleAssertions::assertForbiddenWithout('samples.view', 'get', '/admin/samples');
    ModuleAssertions::assertForbiddenWithout('samples.view', 'get', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertForbiddenWithout('samples.create', 'get', '/admin/samples/create');
    ModuleAssertions::assertForbiddenWithout('samples.create', 'post', '/admin/samples', sampleInput());
    ModuleAssertions::assertForbiddenWithout('samples.edit', 'get', "/admin/samples/{$sample->id}/edit");
    ModuleAssertions::assertForbiddenWithout('samples.edit', 'put', "/admin/samples/{$sample->id}", sampleInput(['lock_version' => $sample->lock_version]));
    ModuleAssertions::assertForbiddenWithout('samples.delete', 'delete', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertForbiddenWithout('samples.delete', 'delete', '/admin/samples', ['ids' => [$sample->id]]);
    ModuleAssertions::assertForbiddenWithout('samples.download', 'get', '/admin/samples/download');

    expect($sample->fresh()?->trashed())->toBeFalse();
});

it('lists and shows contoh records', function (): void {
    $sample = Sample::factory()->create();
    ModuleAssertions::actingAsLevelWith(['samples.view']);

    AssertableInertia::fromTestResponse(get('/admin/samples')->assertOk())
        ->component('Sample::Index')
        ->count('samples.items', 1)
        ->where('samples.items.0.id', $sample->id);

    AssertableInertia::fromTestResponse(get("/admin/samples/{$sample->id}")->assertOk())
        ->component('Sample::Show')
        ->where('sample.id', $sample->id)
        ->where('breadcrumbs.items.1.label', $sample->auditLabel());
});

it('rejects a sort the list does not allow', function (): void {
    ModuleAssertions::actingAsLevelWith(['samples.view']);

    get('/admin/samples?sort=lock_version')->assertStatus(400);
});

it('scopes every contoh query to the signed-in user', function (): void {
    $sample = Sample::factory()->create();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.create', 'samples.edit', 'samples.delete', 'samples.download']);

    ModuleAssertions::assertScopedToUser(Sample::class, 'get', '/admin/samples');
    ModuleAssertions::assertScopedToUser(Sample::class, 'get', "/admin/samples/{$sample->id}");
    ModuleAssertions::assertScopedToUser(Sample::class, 'get', "/admin/samples/{$sample->id}/edit");
    ModuleAssertions::assertScopedToUser(Sample::class, 'put', "/admin/samples/{$sample->id}", sampleInput(['lock_version' => $sample->lock_version]));
    ModuleAssertions::assertScopedToUser(Sample::class, 'delete', '/admin/samples', ['ids' => [$sample->id]]);
    ModuleAssertions::assertScopedToUser(Sample::class, 'delete', "/admin/samples/{$sample->id}");
});

it('creates a contoh and audits it', function (): void {
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.create']);

    post('/admin/samples', sampleInput())->assertSessionHasNoErrors()->assertRedirect();

    $sample = Sample::query()->sole();
    ModuleAssertions::assertAudited($sample, 'created');
});

it('rejects a contoh without its required fields', function (): void {
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.create']);

    post('/admin/samples', [])->assertSessionHasErrors(['nama', 'jumlah', 'tahun', 'harga', 'mulai_tanggal', 'status', 'customer_id']);

    expect(Sample::query()->count())->toBe(0);
});

it('links only a customer the user may see', function (): void {
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.create']);

    ModuleAssertions::assertScopedToUser(Customer::class, 'post', '/admin/samples', sampleInput());
    post('/admin/samples', sampleInput(['customer_id' => Customer::factory()->trashed()->create()->id]))->assertSessionHasErrors('customer_id');
});

it('updates a contoh and audits the change', function (): void {
    $sample = Sample::factory()->create();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.edit']);

    AssertableInertia::fromTestResponse(get("/admin/samples/{$sample->id}/edit")->assertOk())
        ->component('Sample::Edit')
        ->where('sample.lock_version', 0);

    put("/admin/samples/{$sample->id}", sampleInput(['lock_version' => $sample->lock_version]))
        ->assertSessionHasNoErrors()
        ->assertRedirect("/admin/samples/{$sample->id}");

    ModuleAssertions::assertAudited($sample, 'updated');
});

it('gives the second of two saves from the same form a 409 and keeps the first', function (): void {
    $sample = Sample::factory()->create();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.edit']);

    put("/admin/samples/{$sample->id}", sampleInput(['lock_version' => 0]))->assertRedirect();
    put("/admin/samples/{$sample->id}", sampleInput(['lock_version' => 0]))->assertStatus(409);

    expect($sample->fresh()?->lock_version)->toBe(1);
});

it('moves a contoh to the trash and audits it', function (): void {
    $sample = Sample::factory()->create();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.delete']);

    delete("/admin/samples/{$sample->id}")->assertRedirect();

    expect($sample->fresh()?->trashed())->toBeTrue();
    ModuleAssertions::assertAudited($sample, 'deleted');
});

it('deletes the selected records in one audit batch', function (): void {
    [$first, $second] = Sample::factory()->count(2)->create()->all();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.delete']);

    delete('/admin/samples', ['ids' => [$first->id, $second->id]])->assertRedirect();

    expect(Sample::query()->count())->toBe(0)
        ->and(ImmutableActivity::query()->where('event', 'deleted')->pluck('batch_uuid')->unique()->filter())->toHaveCount(1);
});

it('lets only Super Admin see the trash and restore', function (): void {
    $sample = Sample::factory()->create();
    $sample->delete();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.delete']);

    get('/admin/samples/trash')->assertForbidden();
    post('/admin/samples/trash/restore', ['ids' => [$sample->id]])->assertForbidden();

    ModuleAssertions::actingAsSuperAdmin();
    post('/admin/samples/trash/restore', ['ids' => [$sample->id]])->assertRedirect();

    expect($sample->fresh()?->trashed())->toBeFalse();
    ModuleAssertions::assertAudited($sample, 'restored');
});

it('downloads the list as a file and audits one exported row', function (): void {
    Sample::factory()->count(2)->create();
    ModuleAssertions::actingAsLevelWith(['samples.view', 'samples.download']);

    get('/admin/samples/download')->assertOk()->assertDownload();

    expect(ImmutableActivity::query()->where('event', 'exported')->count())->toBe(1);
});
